import numpy as np
def auxvals(L):
    d=dict(length_mm=L,width_mm=6,substrate_mm=.10,piezo_layer_mm=.08,tip_mass_g=.14,damping_ratio=.03)
    r=beam(d); return r
def aest(f0, f, amp, zeta=.03):
    num=2*zeta*f0**2
    den=np.sqrt((f0**2-f**2)**2+(2*zeta*f0*f)**2)
    return amp*num/den
for L in [16,17,17.5,18,18.5,19,20]:
    r=auxvals(L)
    for lab,f0 in [('sc',r['short_circuit_Hz']),('oc',r['open_circuit_Hz'])]:
        print(f"L={L} {lab} f0={f0:.1f} aest_target={aest(f0,210,0.5):.3f} aest_nuis={aest(f0,250,0.8):.3f}")
    print()
